-- RF-104 source package 1.0.0; database revision 1.
-- Run ONLY this file in the existing project's SQL Editor as postgres.
-- Imports an unpublished draft. No release, assignment, schema or scoring changes.
-- An identical rerun is a no-op, including after publication/assignment.
-- Different content under these identifiers aborts instead of overwriting records.
begin;
do $courseimport$
declare
 payload jsonb := $coursedata${"course": {"id": "57d15a1b-42bf-5b91-b376-e82d787fef8c", "slug": "rf-104-understanding-the-hardware-store", "version": 1, "title": "Understanding the Hardware Store", "description": "Learn how a hardware store is organized. Find the right department, follow basic product flow, and connect customers with the right help.", "category": "Retail Foundations", "passing_percent": 80}, "lessons": [{"id": "57c6dafd-b94e-5c78-be50-53d9f25ee03a", "position": 1, "title": "Find Your Way Around the Store", "body": [{"type": "heading", "text": "Why this matters"}, {"type": "paragraph", "text": "Customers expect employees to help them find products. A clear picture of the store makes that easier."}, {"type": "heading", "text": "Lesson content"}, {"type": "heading", "text": "Common store areas"}, {"type": "paragraph", "text": "Most hardware stores have a sales floor, checkout area, receiving area, stockroom, and service counter. Some stores also have a garden center or rental desk. Store layouts vary."}, {"type": "heading", "text": "The sales floor"}, {"type": "paragraph", "text": "The sales floor is where customers shop. Products are often grouped by department. Aisles may include paint, plumbing, electrical, tools, hardware, and lawn and garden."}, {"type": "heading", "text": "Areas behind the scenes"}, {"type": "paragraph", "text": "Receiving is where deliveries are checked. A stockroom holds merchandise that is not on the sales floor. Employees should enter restricted areas only with permission."}, {"type": "heading", "text": "Store maps and signs"}, {"type": "paragraph", "text": "Aisle signs, shelf labels, and store maps can help you locate merchandise. Confirm the location when signs and inventory records do not agree."}, {"type": "heading", "text": "Hardware-store example"}, {"type": "paragraph", "text": "A customer asks for weatherstripping. You know it may be near doors or insulation. You check the store directory and guide the customer to the correct area."}, {"type": "heading", "text": "What to say or do"}, {"type": "bullet", "text": "Learn the names of your store’s main departments."}, {"type": "bullet", "text": "Locate checkout, receiving, and customer service areas."}, {"type": "bullet", "text": "Use approved store maps or coworkers to verify locations."}, {"type": "heading", "text": "Common mistakes"}, {"type": "bullet", "text": "Assuming every hardware store uses the same layout."}, {"type": "bullet", "text": "Sending a customer to an aisle without checking."}, {"type": "heading", "text": "When to ask for help"}, {"type": "paragraph", "text": "Ask a coworker when a department or restricted area is unfamiliar."}, {"type": "heading", "text": "Key takeaways"}, {"type": "bullet", "text": "Know the main store areas."}, {"type": "bullet", "text": "Use signs and approved resources."}, {"type": "bullet", "text": "Verify locations before directing customers."}, {"type": "heading", "text": "Unscored lesson practice"}, {"type": "paragraph", "text": "Question (RF-104-L01-P01): A customer asks for an item in a department you have not visited. What should you do?"}, {"type": "paragraph", "text": "Answer: Check the store map or ask a coworker. Then guide the customer to the correct area."}, {"type": "paragraph", "text": "Explanation: Store layouts vary. Verification is better than guessing."}]}, {"id": "57193363-5dbc-5e6b-9190-0b5c926b4144", "position": 2, "title": "Understand the Main Departments", "body": [{"type": "heading", "text": "Why this matters"}, {"type": "paragraph", "text": "Customers often describe a project instead of a product. Department knowledge helps you decide where to start."}, {"type": "heading", "text": "Lesson content"}, {"type": "heading", "text": "Hardware and fasteners"}, {"type": "paragraph", "text": "This area often includes screws, bolts, nuts, washers, hinges, and other small parts. Size and material matter."}, {"type": "heading", "text": "Tools and power equipment"}, {"type": "paragraph", "text": "Hand tools include hammers, wrenches, and screwdrivers. Power tools include drills and saws. Outdoor power equipment may have its own department."}, {"type": "heading", "text": "Home repair departments"}, {"type": "paragraph", "text": "Plumbing often includes pipe, fittings, and repair parts. Electrical may include switches, outlets, and lighting products. Paint may include coatings, brushes, rollers, and preparation supplies."}, {"type": "heading", "text": "Lawn, garden, and building materials"}, {"type": "paragraph", "text": "Lawn and garden may carry soil, seeds, fertilizers, and hoses. Building materials may include lumber, sheet goods, and concrete products. Not every store carries every category."}, {"type": "heading", "text": "Hardware-store example"}, {"type": "paragraph", "text": "A customer wants to repair a dripping outdoor faucet. You recognize this as a plumbing question. You guide the customer to the plumbing area and help find an experienced associate."}, {"type": "heading", "text": "What to say or do"}, {"type": "bullet", "text": "Learn two common product groups in each department."}, {"type": "bullet", "text": "Ask customers what project they are completing."}, {"type": "bullet", "text": "Refer detailed product questions to trained coworkers."}, {"type": "heading", "text": "Common mistakes"}, {"type": "bullet", "text": "Assuming a product belongs in only one department."}, {"type": "bullet", "text": "Confusing similar-looking parts."}, {"type": "heading", "text": "When to ask for help"}, {"type": "paragraph", "text": "Ask a department specialist before recommending technical parts or products with safety requirements."}, {"type": "heading", "text": "Key takeaways"}, {"type": "bullet", "text": "Learn the purpose of each department."}, {"type": "bullet", "text": "Listen for the customer’s project."}, {"type": "bullet", "text": "Do not guess about technical product fit."}, {"type": "heading", "text": "Unscored lesson practice"}, {"type": "paragraph", "text": "Question (RF-104-L02-P01): A customer asks for a roller cover and painter’s tape. Which department is a good starting point?"}, {"type": "paragraph", "text": "Answer: Paint and decorating."}, {"type": "paragraph", "text": "Explanation: Both items are commonly used for painting projects."}]}, {"id": "d41accd1-52ed-50a4-b5db-21751afde17a", "position": 3, "title": "Follow a Product Through the Store", "body": [{"type": "heading", "text": "Why this matters"}, {"type": "paragraph", "text": "Products must move through several steps before customers can buy them. Each step affects accuracy and availability."}, {"type": "heading", "text": "Lesson content"}, {"type": "heading", "text": "Receiving"}, {"type": "paragraph", "text": "A delivery arrives at the store. Authorized employees check the shipment against the store’s receiving process. They report shortages or damage."}, {"type": "heading", "text": "Storage and stocking"}, {"type": "paragraph", "text": "Products may go directly to shelves or into backstock. Backstock means extra merchandise kept off the sales floor. Products need accurate locations and labels."}, {"type": "heading", "text": "Selling and replenishment"}, {"type": "paragraph", "text": "Customers buy products at checkout or through another approved sales channel. Sales and other inventory changes may update the store’s inventory records. The timing depends on the system."}, {"type": "heading", "text": "Returns and exceptions"}, {"type": "paragraph", "text": "Returns, damaged goods, and special orders follow store-specific procedures. Do not put returned items back on shelves without following those procedures."}, {"type": "heading", "text": "Hardware-store example"}, {"type": "paragraph", "text": "A customer wants a box of deck screws. The shelf is empty. The inventory record shows available stock. You ask an authorized coworker to check the backstock location before making a promise."}, {"type": "heading", "text": "What to say or do"}, {"type": "bullet", "text": "Keep product labels with the correct merchandise."}, {"type": "bullet", "text": "Report damage and quantity differences."}, {"type": "bullet", "text": "Use the store’s approved receiving and return procedures."}, {"type": "heading", "text": "Common mistakes"}, {"type": "bullet", "text": "Treating an inventory count as proof that an item is on the shelf."}, {"type": "bullet", "text": "Putting unverified merchandise into saleable stock."}, {"type": "heading", "text": "When to ask for help"}, {"type": "paragraph", "text": "Ask receiving or inventory staff when counts, locations, or product condition do not match."}, {"type": "heading", "text": "Key takeaways"}, {"type": "bullet", "text": "Products move from receiving to storage or shelves."}, {"type": "bullet", "text": "Accurate locations help customers."}, {"type": "bullet", "text": "Exceptions need approved procedures."}, {"type": "heading", "text": "Unscored lesson practice"}, {"type": "paragraph", "text": "Question (RF-104-L03-P01): The shelf is empty, but the system lists two items. Is the item definitely available?"}, {"type": "paragraph", "text": "Answer: No. Check the location and ask the appropriate employee to verify."}, {"type": "paragraph", "text": "Explanation: Inventory records can differ from physical stock."}]}, {"id": "d3129140-4f73-5b39-9135-23f20335567c", "position": 4, "title": "Know Common Store Services", "body": [{"type": "heading", "text": "Why this matters"}, {"type": "paragraph", "text": "Many customers visit hardware stores for services as well as products. Services differ by location."}, {"type": "heading", "text": "Lesson content"}, {"type": "heading", "text": "Services vary by store"}, {"type": "paragraph", "text": "Some stores offer key cutting, paint mixing, screen repair, propane exchange, delivery, or equipment service. These are examples, not promises about every store."}, {"type": "heading", "text": "Ask before promising"}, {"type": "paragraph", "text": "Services may require trained staff, special equipment, or scheduled hours. Confirm availability, pricing, and turnaround time through approved store resources."}, {"type": "heading", "text": "Understand your role"}, {"type": "paragraph", "text": "You may greet the customer, gather basic details, or direct them to the correct counter. Only trained and authorized employees should operate service equipment."}, {"type": "heading", "text": "Set clear expectations"}, {"type": "paragraph", "text": "Tell customers what has been confirmed. Avoid promising that a service can be completed immediately unless an authorized employee has verified it."}, {"type": "heading", "text": "Hardware-store example"}, {"type": "paragraph", "text": "A customer asks whether the store can cut a replacement key today. You check the service list and ask the trained employee about availability. You then explain the next step."}, {"type": "heading", "text": "What to say or do"}, {"type": "bullet", "text": "Learn which services your store actually offers."}, {"type": "bullet", "text": "Find out who is authorized to perform each service."}, {"type": "bullet", "text": "Verify hours, pricing, and timelines before making promises."}, {"type": "heading", "text": "Common mistakes"}, {"type": "bullet", "text": "Assuming every location offers the same services."}, {"type": "bullet", "text": "Operating service equipment without training."}, {"type": "heading", "text": "When to ask for help"}, {"type": "paragraph", "text": "Ask the service lead or manager when availability, pricing, or authorization is unclear."}, {"type": "heading", "text": "Key takeaways"}, {"type": "bullet", "text": "Services differ by store."}, {"type": "bullet", "text": "Verify details before promising."}, {"type": "bullet", "text": "Use trained staff for service equipment."}, {"type": "heading", "text": "Unscored lesson practice"}, {"type": "paragraph", "text": "Question (RF-104-L04-P01): A customer asks for same-day screen repair. You do not know the schedule. What should you say?"}, {"type": "paragraph", "text": "Answer: Let me check whether we offer that service and what the current turnaround time is."}, {"type": "paragraph", "text": "Explanation: Confirm service availability before setting expectations."}]}, {"id": "62e54d5f-72f0-55a2-b5ee-4c4d36ea24a6", "position": 5, "title": "Connect Customers With the Right Help", "body": [{"type": "heading", "text": "Why this matters"}, {"type": "paragraph", "text": "You do not need to know every product or service. You do need to help customers reach the right resource."}, {"type": "heading", "text": "Lesson content"}, {"type": "heading", "text": "Start with the need"}, {"type": "paragraph", "text": "Listen to the customer’s project or request. Repeat the key detail in simple words to confirm your understanding."}, {"type": "heading", "text": "Choose a resource"}, {"type": "paragraph", "text": "Use aisle signs for locations. Use approved inventory tools for stock checks. Use service lists for store services. Ask trained coworkers about specialized products."}, {"type": "heading", "text": "Make a useful handoff"}, {"type": "paragraph", "text": "A handoff means passing a customer request to another employee. Share the important facts. Do not make the customer repeat the whole story when you can help."}, {"type": "heading", "text": "Follow through"}, {"type": "paragraph", "text": "Confirm that the customer has reached the right person or next step. Do not leave a customer waiting without an update."}, {"type": "heading", "text": "Know when to stop"}, {"type": "paragraph", "text": "Do not give instructions for licensed work or make unsupported safety claims. Refer technical questions to qualified people and approved manufacturer guidance."}, {"type": "heading", "text": "Hardware-store example"}, {"type": "paragraph", "text": "A customer needs a part for a ceiling fan. You ask for the model information. You connect the customer with an associate who can check compatible replacement parts. You share the model details during the handoff."}, {"type": "heading", "text": "What to say or do"}, {"type": "bullet", "text": "Listen and confirm the customer’s request."}, {"type": "bullet", "text": "Choose the right department, resource, or trained coworker."}, {"type": "bullet", "text": "Share useful details during a handoff."}, {"type": "bullet", "text": "Confirm the next step with the customer."}, {"type": "heading", "text": "Common mistakes"}, {"type": "bullet", "text": "Guessing a product location or fit."}, {"type": "bullet", "text": "Pointing vaguely across the store."}, {"type": "bullet", "text": "Leaving the customer without a clear next step."}, {"type": "heading", "text": "When to ask for help"}, {"type": "paragraph", "text": "Ask a manager or trained coworker when the request involves technical compatibility, service promises, or safety."}, {"type": "heading", "text": "Key takeaways"}, {"type": "bullet", "text": "Listen before directing."}, {"type": "bullet", "text": "Use the right store resource."}, {"type": "bullet", "text": "Give clear handoffs."}, {"type": "bullet", "text": "Confirm the next step."}, {"type": "heading", "text": "Unscored lesson practice"}, {"type": "paragraph", "text": "Question (RF-104-L05-P01): You cannot identify a replacement part. What information should you share with a specialist?"}, {"type": "paragraph", "text": "Answer: Share the customer’s project, the old part or model details, and what you have already checked."}, {"type": "paragraph", "text": "Explanation: A clear handoff saves time and reduces confusion."}]}], "questions": [{"id": "bb22a016-4614-5dda-a23c-353ac2254d09", "position": 1, "prompt": "A customer asks where to find a product. You do not know the aisle. What is the best next step?", "options": ["Guess the most likely aisle.", "Check an approved store map or ask a coworker.", "Tell the customer to search every aisle.", "Send the customer to receiving."], "correct_option": 1, "explanation": "Store layouts vary. Use an approved resource or coworker to confirm the location."}, {"id": "ec8a61a5-c219-5416-9db4-f9f7799d8c6a", "position": 2, "prompt": "A customer needs a roller cover and painter’s tape. Where should you start?", "options": ["Plumbing.", "Electrical.", "Paint and decorating.", "Outdoor power equipment."], "correct_option": 2, "explanation": "Roller covers and painter’s tape are common paint supplies."}, {"id": "1c10b554-080c-5ee2-b9aa-65a9a3ed593d", "position": 3, "prompt": "The shelf is empty, but the inventory record shows stock. What should you do?", "options": ["Promise the customer the item is available.", "Change the count to zero without checking.", "Tell the customer inventory records are always wrong.", "Check approved stock locations or ask an authorized coworker to verify."], "correct_option": 3, "explanation": "A system quantity is not proof of physical availability. Verify before making a promise."}, {"id": "5e687190-7cba-508b-be2d-14c2d10dd221", "position": 4, "prompt": "A customer asks for a service you have never seen offered at your store. What should you do?", "options": ["Confirm the service list and ask authorized staff before promising it.", "Promise the service and decide who will do it later.", "Try the service equipment without training.", "Say every hardware store offers the same services."], "correct_option": 0, "explanation": "Store services differ. Verify availability and use trained staff."}, {"id": "cc6e7da4-b740-556a-a826-5039327190b7", "position": 5, "prompt": "You bring a customer to a department specialist. Which handoff is best?", "options": ["Leave without speaking.", "Tell the specialist only that the customer needs help.", "Share the customer’s project and the details already collected.", "Ask the customer to restart the conversation from the beginning."], "correct_option": 2, "explanation": "A useful handoff shares relevant facts and helps the next employee continue the work."}], "catalog": {"course_code": "RF-104", "skill_level": "foundations", "topics": ["Store operations", "Departments", "Customer service"], "keywords": ["store layout", "receiving", "backstock", "store services", "customer handoff"], "learning_paths": ["New Retail Employee"]}}$coursedata$::jsonb;
 c jsonb; l jsonb; q jsonb; target uuid;
begin
 c := payload->'course'; target := (c->>'id')::uuid;
 perform pg_advisory_xact_lock(hashtextextended('coltrain-course:' || target::text, 0));
 if exists(select 1 from public.training_courses where id=target) then
  if not exists(select 1 from public.training_courses t where t.id=target
   and t.slug=c->>'slug' and t.version=(c->>'version')::integer
   and t.title=c->>'title' and t.description=c->>'description'
   and t.category=c->>'category' and t.passing_percent=(c->>'passing_percent')::integer
   and t.owner_organization_id is null) then
   raise exception 'RF-104 course differs; create a new version rather than overwrite';
  end if;
  if (select count(*) from public.training_lessons where course_id=target) <> jsonb_array_length(payload->'lessons')
   or (select count(*) from public.training_questions where course_id=target) <> jsonb_array_length(payload->'questions') then
   raise exception 'RF-104 content differs; draft import was not changed';
  end if;
  for l in select value from jsonb_array_elements(payload->'lessons') loop
   if not exists(select 1 from public.training_lessons t where t.id=(l->>'id')::uuid
    and t.course_id=target and t.position=(l->>'position')::integer
    and t.title=l->>'title' and t.body=l->'body') then
    raise exception 'RF-104 lesson differs; draft import was not changed';
   end if;
  end loop;
  for q in select value from jsonb_array_elements(payload->'questions') loop
   if not exists(select 1 from public.training_questions t join private.training_answer_keys k on k.question_id=t.id
    where t.id=(q->>'id')::uuid and t.course_id=target and t.position=(q->>'position')::integer
    and t.prompt=q->>'prompt' and t.options=q->'options'
    and k.correct_option=(q->>'correct_option')::integer and k.explanation=q->>'explanation') then
    raise exception 'RF-104 question differs; draft import was not changed';
   end if;
  end loop;
 else
  insert into public.training_courses(id,slug,version,title,description,category,passing_percent,published)
   values(target,c->>'slug',(c->>'version')::integer,c->>'title',c->>'description',c->>'category',(c->>'passing_percent')::integer,false);
  for l in select value from jsonb_array_elements(payload->'lessons') loop
   insert into public.training_lessons(id,course_id,position,title,body)
    values((l->>'id')::uuid,target,(l->>'position')::integer,l->>'title',l->'body');
  end loop;
  for q in select value from jsonb_array_elements(payload->'questions') loop
   insert into public.training_questions(id,course_id,position,prompt,options)
    values((q->>'id')::uuid,target,(q->>'position')::integer,q->>'prompt',q->'options');
   insert into private.training_answer_keys(question_id,correct_option,explanation)
    values((q->>'id')::uuid,(q->>'correct_option')::integer,q->>'explanation');
  end loop;
 end if;
 -- Optional metadata: imports remain compatible before the catalog migration.
 if to_regclass('public.training_course_catalog') is not null then
  insert into public.training_course_catalog(course_id,course_code,skill_level,topics,keywords,learning_paths)
  values(target,payload->'catalog'->>'course_code',payload->'catalog'->>'skill_level',
   array(select jsonb_array_elements_text(payload->'catalog'->'topics')),
   array(select jsonb_array_elements_text(payload->'catalog'->'keywords')),
   array(select jsonb_array_elements_text(payload->'catalog'->'learning_paths')))
  on conflict(course_id) do nothing;
 end if;
end;
$courseimport$;
commit;
select slug,title,published,
 (select count(*) from public.training_lessons where course_id=c.id) as lessons,
 (select count(*) from public.training_questions where course_id=c.id) as quiz_questions
from public.training_courses c where id='57d15a1b-42bf-5b91-b376-e82d787fef8c';
